// Records the demo video: the test page (big screen and two phones) while a sample quiz is played,
// with captions and a voice-over (generated by voice.py), and the soundtrack question's music. Writes docs/media/demo.mp4,
// its captions (demo.vtt) and a transcript (demo-transcript.md).
//
//   just demo-video
const path = require('path');
const fs = require('fs');
const { execFileSync } = require('child_process');
const L = require('./lib.js');
const sample = require('./sample.js');

const OUT = path.resolve(__dirname, '../../docs/media');
const FRAMES = path.join(__dirname, 'out/frames');
const VOICE = path.join(__dirname, 'out/voice');
const LINES = JSON.parse(fs.readFileSync(path.join(__dirname, 'narration.json'), 'utf8'));
const DURATIONS = JSON.parse(fs.readFileSync(path.join(VOICE, 'manifest.json'), 'utf8'));
/** Pause after each spoken line. */
const BREATH_MS = 600;
/** The sample quiz's soundtrack, as the test server stored it. */
const TUNE = path.resolve(__dirname, '../../target/e2e/data/media', 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa3.wav');

/**
 * Records the page with Chrome's screencast: every frame keeps the time it was painted, and the
 * video shows each one for exactly as long as it was on screen, so it runs on the same clock as
 * the narration. (Puppeteer's recorder stretched the video and dropped its end.)
 * `stop()` returns the first frame's time (ms since the epoch) and an ffmpeg concat list.
 */
async function record(page) {
  fs.rmSync(FRAMES, { recursive: true, force: true });
  fs.mkdirSync(FRAMES, { recursive: true });
  const cdp = await page.createCDPSession();
  const frames = [];
  cdp.on('Page.screencastFrame', ({ data, metadata, sessionId }) => {
    const file = path.join(FRAMES, `${String(frames.length).padStart(6, '0')}.jpg`);
    fs.writeFileSync(file, Buffer.from(data, 'base64'));
    frames.push({ file, at: metadata.timestamp * 1000 });
    cdp.send('Page.screencastFrameAck', { sessionId }).catch(() => {});
  });
  await cdp.send('Page.startScreencast', { format: 'jpeg', quality: 90, everyNthFrame: 1 });
  return {
    async stop() {
      const end = Date.now();
      await cdp.send('Page.stopScreencast');
      const lines = [];
      frames.forEach((frame, i) => {
        const until = i + 1 < frames.length ? frames[i + 1].at : end;
        lines.push(`file '${frame.file}'`, `duration ${((until - frame.at) / 1000).toFixed(4)}`);
      });
      // The concat demuxer needs the last file listed again for its duration to count.
      lines.push(`file '${frames[frames.length - 1].file}'`);
      const list = path.join(FRAMES, 'list.txt');
      fs.writeFileSync(list, lines.join('\n') + '\n');
      return { origin: frames[0].at, list };
    },
  };
}

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const ctx = await L.setup(sample.quiz(), { joker: true });
  const pictures = sample.avatars(path.join(__dirname, 'out/avatars'));

  // A test game played by two named teams instead of "Phone 1" and "Phone 2".
  const code = await L.api('/api/admin/test/start', { token: ctx.token, quiz_id: ctx.id });
  for (const phone of (await L.api('/api/admin/test/info', { token: ctx.token, code })).phones) {
    await L.api('/api/admin/test/remove-phone', { token: ctx.token, code, ticket: phone.ticket });
  }
  const teams = [['The Quizzly Bears', 'bears'], ['Trivia Newton-John', 'newton']];
  for (const [name] of teams) await L.api('/api/game/join', { code, name });

  const page = await L.openAdmin(ctx, `/admin/test/${code}`, 1600, 900);
  await page.waitForFunction(() => document.querySelectorAll('.test-phone iframe').length === 2, { timeout: 90000 });
  const host = () => page.frames().find((f) => f.url().includes('/host/'));
  const phones = () => page.frames().filter((f) => f.url().includes('/join/'));
  for (const [i, [, picture]] of teams.entries()) {
    const phone = phones()[i];
    await phone.waitForSelector('input[type=file]', { timeout: 60000 });
    await (await phone.$('input[type=file]')).uploadFile(pictures[picture]);
    await phone.waitForSelector('img.avatar', { timeout: 30000 });
  }
  await L.sleep(1500);

  // Captions over the page.
  const caption = (text) => page.evaluate((text) => {
    let el = document.getElementById('demo-caption');
    if (!el) {
      el = document.createElement('div');
      el.id = 'demo-caption';
      el.style.cssText = 'position:fixed;left:50%;top:8px;transform:translateX(-50%);z-index:99;'
        + 'background:#ffb703;color:#14121f;font:700 22px system-ui,sans-serif;padding:10px 22px;'
        + 'border-radius:999px;box-shadow:0 6px 24px rgb(0 0 0/.5);transition:opacity .3s';
      document.body.appendChild(el);
    }
    el.textContent = text;
    el.style.opacity = text ? '1' : '0';
  }, text);
  const next = async (wait = 1800) => { await host().evaluate(() => document.querySelector('.host-controls .button.primary')?.click()); await L.sleep(wait); };
  const tap = async (i, n) => { const f = phones()[i]; await f.waitForSelector('.phone-answer', { timeout: 15000 }); (await f.$$('.phone-answer'))[n].click(); await L.sleep(700); };
  const type = async (i, texts) => {
    const f = phones()[i];
    await f.waitForSelector('.open-form input', { timeout: 15000 });
    const fields = await f.$$('.open-form input');
    for (const [k, t] of [texts].flat().entries()) await fields[k].type(t, { delay: 60 });
    await L.sleep(300);
    await (await f.$('.open-form button[type=submit]')).click();
    await L.sleep(700);
  };

  const recorder = await record(page);
  const started = Date.now();
  const cues = [];
  /** Shows a line's caption, runs `actions`, and lasts at least as long as the line is spoken. */
  const step = async (id, actions = async () => {}, extraMs = 0) => {
    const line = LINES.find((l) => l.id === id);
    const at = Date.now() - started;
    cues.push({ id, at, ms: DURATIONS[id] });
    await caption(line.caption);
    await actions();
    const left = at + DURATIONS[id] + BREATH_MS + extraMs - (Date.now() - started);
    if (left > 0) await L.sleep(left);
  };
  const submit = (f) => f.evaluate(() => [...document.querySelectorAll('button')].find((b) => b.innerText.includes('Submit')).click());

  await L.sleep(800);
  await step('intro');
  await step('join');
  await step('slide', () => next(0));
  await step('choice', async () => { await next(1200); await tap(0, 1); await tap(1, 0); }, 1200);
  await step('truefalse', async () => { await next(800); await tap(1, 0); await tap(0, 0); }, 1500);
  await step('typed', async () => { await next(800); await type(0, 'Canberra'); await type(1, 'Sydney'); }, 1200);
  await step('number', async () => { await next(800); await type(0, '88'); await type(1, '76'); }, 1500);
  await step('order', async () => {
    await next(800);
    for (const [i, order] of [[0, ['Pyramids of Giza', 'Colosseum', 'Eiffel Tower', 'Burj Khalifa']], [1, ['Colosseum', 'Pyramids of Giza', 'Eiffel Tower', 'Burj Khalifa']]]) {
      const f = phones()[i];
      await f.waitForSelector('.order-choice', { timeout: 15000 });
      const items = await f.$$eval('.order-choice span:last-child', (e) => e.map((x) => x.innerText));
      for (const item of order) { (await f.$$('.order-choice'))[items.indexOf(item)].click(); await L.sleep(250); }
      await submit(f);
      await L.sleep(500);
    }
  }, 1500);
  await step('parts', async () => { await next(800); await type(0, ['Leonardo da Vinci', 'Paris']); await type(1, ['Michelangelo', 'Paris']); }, 1500);
  await step('pin', async () => {
    await next(800);
    for (const [i, at] of [[0, [0.52, 0.66]], [1, [0.32, 0.42]]]) {
      const f = phones()[i];
      await f.waitForSelector('.pin-map image', { timeout: 15000 });
      const img = await f.$('.pin-map image');
      const b = await img.boundingBox();
      await img.click({ offset: { x: b.width * at[0], y: b.height * at[1] } });
      await L.sleep(400);
      await submit(f);
      await L.sleep(500);
    }
  }, 2000);
  // Answers wait until the line is nearly spoken, so the picture stays up while it is talked about.
  await step('picture', async () => { await next(Math.max(DURATIONS.picture - 300, 1200)); await tap(0, 0); await tap(1, 2); }, 1500);
  // The question asks its riddle first; the music starts once the line is spoken.
  let musicAt = 0;
  await step('music', async () => {
    await next(0);
    await L.sleep(Math.max(DURATIONS.music - 1500, 0));
    musicAt = Date.now() - started;
    await next(3000);
    await tap(0, 0);
    await tap(1, 1);
  }, 3500);
  await step('podium', async () => {
    for (let i = 0; i < 4; i++) {
      if (await host().$('.host-controls a.button')) break;
      await next(2200);
    }
  }, 1500);
  await step('outro', () => {}, 1500);
  const { origin, list } = await recorder.stop();
  // Cues relative to the first frame, which is where the video starts.
  for (const cue of cues) cue.at += started - origin;
  musicAt += started - origin;

  // The voice-over: each line placed where its step started, mixed into one track.
  const inputs = ['-f', 'concat', '-safe', '0', '-i', list];
  const filters = [];
  cues.forEach((cue, k) => {
    inputs.push('-i', path.join(VOICE, `${cue.id}.wav`));
    filters.push(`[${k + 1}:a]adelay=${cue.at}|${cue.at}[v${k}]`);
  });
  // The big screen's music, which the screencast cannot hear, where the host started it.
  inputs.push('-i', TUNE);
  filters.push(`[${cues.length + 1}:a]volume=0.6,adelay=${musicAt}|${musicAt}[music]`);
  const mix = `${filters.join(';')};${cues.map((_, k) => `[v${k}]`).join('')}[music]amix=inputs=${cues.length + 1}:normalize=0[voice]`;
  // H.264 and AAC in MP4: plays everywhere and stays small.
  execFileSync('ffmpeg', ['-loglevel', 'error', '-y', ...inputs, '-filter_complex', mix,
    '-map', '0:v', '-map', '[voice]', '-vf', 'fps=30,scale=1280:-2', '-c:v', 'libx264', '-preset', 'slow', '-crf', '30',
    '-pix_fmt', 'yuv420p', '-c:a', 'aac', '-b:a', '96k', '-movflags', '+faststart', path.join(OUT, 'demo.mp4')]);
  execFileSync('ffmpeg', ['-loglevel', 'error', '-y', '-ss', '9', '-i', path.join(OUT, 'demo.mp4'), '-frames:v', '1',
    '-q:v', '80', path.join(OUT, 'demo-poster.webp')]);

  // Captions (WebVTT) and a transcript of what is said.
  const stamp = (ms) => new Date(ms).toISOString().slice(11, 23);
  const vtt = ['WEBVTT', ''];
  for (const [k, cue] of cues.entries()) {
    const line = LINES.find((l) => l.id === cue.id);
    vtt.push(`${k + 1}`, `${stamp(cue.at)} --> ${stamp(cue.at + cue.ms + BREATH_MS)}`, line.text, '');
  }
  fs.writeFileSync(path.join(OUT, 'demo.vtt'), vtt.join('\n'));
  // A Markdown fragment, included by docs/demo.md.
  const transcript = [...cues.map((cue) => `- **${stamp(cue.at).slice(3, 8)}** ${LINES.find((l) => l.id === cue.id).text}`), ''];
  fs.writeFileSync(path.join(OUT, 'demo-transcript.md'), transcript.join('\n'));
  console.log('demo video:', fs.statSync(path.join(OUT, 'demo.mp4')).size, 'bytes');
  console.log('ERRORS', ctx.errors.length ? ctx.errors.join('\n') : 'none');
  await ctx.browser.close();
})().catch((e) => { console.error('FAILED', e); process.exit(1); });
